void operator delete(void*);

class entity
{
  char data_[508];

public:
  virtual ~entity();
};

class mat_fac
{
public:
  virtual ~mat_fac();
};

struct vector3d
{
  float x;
  float y;
  float z;
};

template <class T>
class vector
{
  T* start_;
  T* finish_;
  T* end_;

public:
  ~vector()
  {
    if (start_ != 0)
      operator delete(start_);
  }
};

class b_spline
{
  vector<vector3d> control_pts;
  vector<vector3d> curve_pts;
  int sub_divisions;
  int spline_type;
  bool force_start;

public:
  ~b_spline()
  {
  }
};

class polytube : public entity
{
  bool use_spline;
  b_spline spline;
  mat_fac* my_material;
  float tube_radius;
  int num_sides;
  float tiles_per_meter;
  float max_length;

public:
  virtual ~polytube();
};

__asm__(".equ _$_6entity,0x001298C8");
__asm__(".equ _$_7mat_fac,0x002BC998");
__asm__(".equ __builtin_delete,0x002AC6B0");

polytube::~polytube()
{
  if (my_material != 0)
  {
    delete my_material;
    my_material = 0;
  }
}
